int binarySearch(const std::vector<int>& data, int low, int high, int key) {
    if (low > high) return -1;                 // 基线：区间空了
    const int mid = low + (high - low) / 2;
    if (data[mid] == key) return mid;
    if (data[mid] < key) return binarySearch(data, mid + 1, high, key);
    return binarySearch(data, low, mid - 1, key);
}

int main() {
    const std::vector<int> data{1, 3, 5, 7, 9, 11};
    for (int key : {1, 9, 4}) {
        std::cout << key << " -> " << binarySearch(data, 0, 5, key) << '\n';
    }
}

