void permute(std::string& text, std::size_t start) {
    if (start == text.size()) {          // 基线：没有位置可换了
        std::cout << text << '\n';
        return;
    }
    for (std::size_t i = start; i < text.size(); ++i) {
        std::swap(text[start], text[i]);
        permute(text, start + 1);
        std::swap(text[start], text[i]);  // 换回来，才能试下一个 i
    }
}

