bool hasSubset(const std::vector<int>& values, std::size_t index, int target) {
    if (target == 0) return true;                                   // 正好凑够
    if (index == values.size() || target < 0) return false;          // 没得选 / 超了
    return hasSubset(values, index + 1, target - values[index])      // 选它
        || hasSubset(values, index + 1, target);                     // 不选
}

