#include <cstdlib>
#include <iostream>
#include <vector>

bool safe(const std::vector<int>& rows, int column, int row) {
    for (int c = 0; c < column; ++c) {
        if (rows[c] == row) return false;                          // 同一行
        if (std::abs(rows[c] - row) == column - c) return false;    // 同一斜线
    }
    return true;
}

void place(std::vector<int>& rows, int column, int n, int& count) {
    if (column == n) { ++count; return; }         // 每列都放好了
    for (int row = 0; row < n; ++row) {
        if (!safe(rows, column, row)) continue;
        rows[column] = row;                        // 放
        place(rows, column + 1, n, count);         // 试下一列
    }                                              // 回来时下一次循环自动覆盖，等于撤销
}

int main() {
    for (int n : {4, 6, 8}) {
        std::vector<int> rows(n, 0);
        int count = 0;
        place(rows, 0, n, count);
        std::cout << n << " 皇后：" << count << " 种解" << '\n';
    }
}

#include <iostream>
#include <vector>

int countPaths(std::vector<std::vector<char>>& grid, int r, int c) {
    if (r < 0 || c < 0 || r >= static_cast<int>(grid.size())
        || c >= static_cast<int>(grid[0].size()) || grid[r][c] == '#') return 0;
    if (r == static_cast<int>(grid.size()) - 1
        && c == static_cast<int>(grid[0].size()) - 1) return 1;

    grid[r][c] = '#';                                  // 标记，防止原地打转
    int total = countPaths(grid, r + 1, c) + countPaths(grid, r, c + 1);
    grid[r][c] = '.';                                  // 撤销，别的路径还要用
    return total;
}

int main() {
    std::vector<std::vector<char>> grid{
        {'.', '.', '.'},
        {'.', '#', '.'},
        {'.', '.', '.'},
    };
    std::cout << "从左上到右下的路径数：" << countPaths(grid, 0, 0) << '\n';
}

