#include <iostream>
#include <vector>

int linearCount(const std::vector<int>& data, int key) {
    int count = 0;
    for (int value : data) {
        ++count;
        if (value == key) break;
    }
    return count;
}

int binaryCount(const std::vector<int>& data, int key) {
    int low = 0;
    int high = static_cast<int>(data.size()) - 1;
    int count = 0;
    while (low <= high) {
        const int mid = low + (high - low) / 2;
        ++count;
        if (data[mid] == key) break;
        if (data[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return count;
}

int main() {
    std::vector<int> data;
    for (int i = 1; i <= 1000; i += 2) data.push_back(i);   // 1,3,5,...,999

    std::cout << "n = " << data.size() << '\n';
    for (int key : {1, 999, 1000}) {
        std::cout << "找 " << key << "：线性 " << linearCount(data, key)
                  << " 次，二分 " << binaryCount(data, key) << " 次" << '\n';
    }
}

#include <iostream>
#include <vector>

void bubbleSort(std::vector<int> data, int& comparisons, int& swaps) {
    comparisons = 0;
    swaps = 0;
    for (std::size_t i = 0; i + 1 < data.size(); ++i) {
        for (std::size_t j = 0; j + 1 < data.size() - i; ++j) {
            ++comparisons;
            if (data[j] > data[j + 1]) {
                std::swap(data[j], data[j + 1]);
                ++swaps;
            }
        }
    }
}

int main() {
    for (const std::vector<int> input : {std::vector<int>{1, 2, 3, 4, 5},
                                         std::vector<int>{5, 4, 3, 2, 1}}) {
        int comparisons = 0;
        int swaps = 0;
        bubbleSort(input, comparisons, swaps);
        std::cout << "比较 " << comparisons << " 次，交换 " << swaps << " 次" << '\n';
    }
}

