#include <iostream>
#include <vector>

class RingQueue {
public:
    explicit RingQueue(int capacity) : data_(capacity), head_(0), count_(0) {}

    bool push(int value) {
        if (count_ == static_cast<int>(data_.size())) return false;
        const int tail = (head_ + count_) % static_cast<int>(data_.size());
        data_[tail] = value;
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (count_ == 0) return false;
        out = data_[head_];
        head_ = (head_ + 1) % static_cast<int>(data_.size());
        --count_;
        return true;
    }

    int size() const { return count_; }

private:
    std::vector<int> data_;
    int head_;
    int count_;
};

int main() {
    RingQueue queue(3);
    for (int value : {1, 2, 3, 4}) {
        std::cout << "push " << value << (queue.push(value) ? " 成功" : " 失败（满了）") << '\n';
    }
    int value = 0;
    while (queue.pop(value)) std::cout << value << ' ';
    std::cout << '\n';
}

