    else if (value > root->value) root->right = insert(root->right, value);
    return root;                       // 相等就忽略（集合语义）
}

void inorder(const Node* root) {
    if (root == nullptr) return;
    inorder(root->left);
    std::cout << root->value << ' ';
    inorder(root->right);
}

int main() {
    Node* root = nullptr;
    for (int value : {50, 30, 70, 20, 40}) root = insert(root, value);
    inorder(root);
    std::cout << '\n';
}

