#include <cctype>
#include <iostream>
#include <string>

bool isPalindrome(const std::string& text) {
    std::string clean;
    for (char ch : text) {
        if (std::isalnum(static_cast<unsigned char>(ch))) {
            clean += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        }
    }

    std::size_t left = 0;
    std::size_t right = clean.size();
    while (left + 1 < right) {
        --right;
        if (clean[left] != clean[right]) return false;
        ++left;
    }
    return true;
}

int main() {
    for (const std::string text : {"A man, a plan, a canal: Panama", "hello"}) {
        std::cout << '"' << text << "\" -> "
                  << (isPalindrome(text) ? "是回文" : "不是回文") << '\n';
    }
}
